<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">Create New Column</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              label="Title*"
              v-model="new_model['title']"
              hint="Only use Words and numbers"
              outlined
              class="full-width"
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-checkbox
              :label="$t('is_it_required')"
              v-model="new_model['column_required']"
              size="30px"
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              v-model="new_model['type']"
              class="col-sm-6 col-md-6 col-lg-6"
              :options="column_type"
              :label="$t('select_column_type') + '*'"
              emit-value
              map-options
              error-message="Field is required"
              :error="new_model['type_error']"
            >
              <template v-slot:append>
                <q-icon
                  name="close"
                  @click.stop="new_model['type'] = ''"
                  class="cursor-pointer"
                />
              </template>
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              tabindex="0"
              v-model="new_model['table_name']"
              error-message="Field is required"
              :error="new_model['table_name_error']"
              :options="tables_list"
              emit-value
              map-options
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';

import { api, getAuthorizationToken } from 'pages/APIs';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { onlyNumbersAndCharacters } from 'src/utils/general';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
    tables_list: [] as any,
    columns_list: {} as any,
  },
  components: {},
  data() {
    return {
      column_type: [
        { label: 'Select Type', value: '' },
        { label: this.$t('amount'), value: 'AMOUNT' },
        { label: 'STRING', value: 'STRING' },
        { label: this.$t('invoice_date'), value: 'DATE' },
        { label: this.$t('number'), value: 'NUMBER' },
        { label: 'BOOLEAN', value: 'BOOLEAN' },
        { label: this.$t('currency'), value: 'CURRENCY' },
      ],
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_model: ref(model),
      token: ref(''),
      data_types: ref([] as any),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['column_required'] = false;
      this.new_model['title'] = '';
      this.new_model['type'] = '';
      this.new_model['table_name'] = '';
      this.new_model['type_error'] = false;
      this.new_model['title_error'] = false;
      this.new_model['table_name_error'] = false;
      this.new_model['title_error_msg'] = '';
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let response: any;

      this.setColumnName();
      let formData = new FormData();
      formData.append('column_name', this.new_model['column_name']);
      formData.append('column_type', this.new_model['type']);
      formData.append('title', this.new_model['title']);
      formData.append('is_required', this.new_model['column_required']);
      formData.append('table_name', this.new_model['table_name']);
      formData.append('org_id', getOrgId());
      let token: string = await this.getToken();
      response = await axios.post(api.create_table_column, formData, {
        headers: {
          Authorization: token,
        },
      });

      if (response.data.success === false) {
        throw { message: response.data.message };
      }

      notify.success('Column Created successfully');

      this.new_model['id'] = response.data.data.id;
      const event = new CustomEvent('column_added', {
        detail: { data: this.new_model },
      });
      document.dispatchEvent(event);
    },

    validateRow(row: any) {
      let error = false;

      this.new_model['title_error'] = false;
      this.new_model['type_error'] = false;
      this.new_model['title_error_msg'] = '';
      this.new_model['table_name_error'] = false;

      let column_name = row['title']
        .replace(/[^0-9a-zA-Z_ ]/g, '')
        .toUpperCase();

      if (!row['title'] || row['title'].length == 0) {
        error = true;
        this.new_model['title_error_msg'] = 'Title is required';
        this.new_model['title_error'] = true;
      } else if (!onlyNumbersAndCharacters(row['title'])) {
        this.new_model['title_error_msg'] =
          'Title can only contain characters, numbers';
        error = true;
        this.new_model['title_error'] = true;
      } else if (this.columns_list.hasOwnProperty(column_name)) {
        this.new_model['title_error_msg'] = 'Title already exists';
        error = true;
        this.new_model['title_error'] = true;
      }

      if (!row['type'] || row['type'].length == 0) {
        this.new_model['type_error'] = true;
      }

      if (!row['table_name'] || row['table_name'].length == 0) {
        this.new_model['table_name_error'] = true;
      }

      return !error;
    },

    setColumnName() {
      this.new_model['column_name'] = '';
      let title = this.new_model['title'];

      this.new_model['column_name'] = title
        .replace(/[^0-9a-zA-Z_ ]/g, '')
        .toUpperCase();
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
  },
});
</script>

