<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">Create New Group</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (!new_model['validate'] || new_model['required_error']
                  ? 'column-error-border'
                  : '')
              "
              v-model="new_model['name']"
              placeholder="Group Name"
              :hint="message"
            >
              <template v-slot:append>
                <q-icon
                  v-if="!new_model['validate'] || new_model['required_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="!new_model['validate']">
                      {{ message }}
                    </template>
                    <template v-if="new_model['required_error']">
                      Field is Required
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import { removeSpacesWithUnderscore, validateString } from 'src/utils/general';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
  },
  components: {},
  data() {
    return {
      message: this.$t('only_characters_numbers'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_model: ref(model),
      token: ref(''),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['name'] = '';
      this.new_model['validate'] = true;
      this.new_model['required_error'] = false;
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let response: any;

      let formData = new FormData();
      formData.append('title', this.new_model['name']);
      formData.append(
        'group_name',
        removeSpacesWithUnderscore(this.new_model['name']),
      );
      formData.append('doc_type_name', this.doc_type);
      formData.append('translation_key', this.new_model['name']);
      formData.append('org_id', getOrgId());

      let token: string = await getAuthorizationToken();
      response = await axios.post(api.create_document_field_group, formData, {
        headers: {
          Authorization: token,
        },
      });

      if (
        response.data &&
        response.data.hasOwnProperty('success') &&
        response.data.success === false
      ) {
        throw { message: response.data.message };
      }

      const event = new CustomEvent('group_added', {
        detail: { data: response.data },
      });
      document.dispatchEvent(event);
      notify.success('Group Created successfully');
      this.setNewModel();
    },

    validateRow(row: any) {
      let validate = true;

      if (!row['name'] || row['name'].length == 0) {
        row.required_error = true;
        return false;
      }

      if (!validateString(row['name'])) {
        row.validate = false;
        return false;
      }

      return validate;
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
  },
});
</script>

<style lang="scss" scoped></style>
