<!--vbase-->
<template>
  <!-- Groups List -->
  <div class="flex flex-col gap-3">
    <!-- Toolbar -->
    <div class="flex items-center gap-2">
      <q-btn
        color="primary"
        class="mr-6"
        :label="$t('add_new')"
        @click="addNewDialog = true"
      />

      <q-btn
        color="primary"
        class="mr-6"
        :label="$t('clone_document_type')"
        @click="cloneGroupsAndFieldsDlg = true"
      />

      <q-space />
      <q-input outlined debounce="300" color="primary" v-model="filter">
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="doc_type_groups_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      flat-style
      table-height="350px"
      @row-action="handleRowAction"
    >
      <template #body-cell-name="{ row }">
        <q-input
          borderless
          tabindex="0"
          v-model="row.name"
          :readonly="row.id !== ''"
        />
      </template>
    </DocBitsTable>
  </div>
  <!-- END Groups List -->

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

  <!-- Add New  -->
  <q-dialog
    v-model="addNewDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <CreateGroup :doc_type="doc_type" />
  </q-dialog>

  <q-dialog
    v-model="cloneGroupsAndFieldsDlg"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card style="width: 600px">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">Clone Groups and Fields</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="row">
          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-select
              v-model="copyFromDocType"
              outlined
              data-cy="doc-type"
              :options="doc_type_list"
              emit-value
              map-options
              :label="$t('document_type')"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          data-cy="cancel"
          color="primary"
          v-close-popup
        />
        <q-btn
          flat
          :label="$t('proceed')"
          data-cy="delete-popup"
          color="primary"
          v-close-popup
          @click="cloneGroupsAndFields()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Add New -->

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import axios from 'axios';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import type { dynamicObj } from 'src/pages/assets';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import CreateGroup from 'src/pages/Settings/CreateDocType/CreateGroup.vue';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [displayFieldLabel, helperMixin],
  props: {
    doc_type: {
      type: String,
      default: '',
    },
    list_data: {} as any,
  },
  components: {
    CreateGroup,
    Loader,
    DocBitsTable,
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const lowerSearch = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        for (const [_key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(lowerSearch)) return true;
        }
        return false;
      });
    },
  },
  setup() {
    let data: any = [];
    const columns = ref(data);
    const dropdown_store = useDropdownStore();
    const { doc_type_list } = dropdown_store;

    const rowActions: RowActionItem[] = [
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: any) => row.id !== '' && row.org_id !== DEFAULT_ORG_UUID,
      },
    ];

    return {
      columns,
      filter: ref(''),
      rows: ref(data),
      doc_type_list,
      loading: ref(false),
      copyFromDocType: ref(),
      addNewDialog: ref(false),
      cloneGroupsAndFieldsDlg: ref(false),
      rowActions,
    };
  },
  watch: {
    list_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.prepareRows(newVal);
        }, 0);
      },
    },
  },
  mounted: function () {
    this.prepareColumns();
    this.prepareRows(this.list_data);
    document.addEventListener('group_added', this.recordAdded);
  },
  unmounted: function () {
    // event listeners
    document.removeEventListener('group_added', this.recordAdded);
  },
  methods: {
    prepareListView(data: any) {
      this.prepareRows(data);
    },
    prepareColumns() {
      this.columns = [
        {
          name: 'name',
          label: this.$t('groups'),
          field: 'name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },
    prepareRows(data: any) {
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },
    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      newRow['name'] = this.displayFieldLabel(row);
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === row.id);
        if (index !== -1) {
          this.handleDelete(row.id, index);
        }
      }
    },
    async handleDelete(id: any, index: number) {
      try {
        if (id === '') {
          return;
        }
        this.loading = true;
        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.delete(
          addOrgIdQueryString(api.delete_document_field_group + '/' + id),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        const event = new CustomEvent('group_deleted', {
          detail: { index: index },
        });
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    recordAdded(e: any) {
      this.addNewDialog = false;
    },

    async cloneGroupsAndFields() {
      this.cloneGroupsAndFieldsDlg = false;

      this.showLoading();
      let response: any;
      try {
        let token: string = await getAuthorizationToken();
        let queryStr =
          '?copy_from_doc_type=' +
          this.copyFromDocType +
          '&copy_to_doc_type=' +
          this.doc_type;
        response = await axios.get(
          addOrgIdQueryString(api.copy_fields_setting_from_doc_type + queryStr),
          {
            headers: {
              Authorization: token,
            },
          },
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      if (response.data.success === false) {
        notify.error(response.data.message);
        this.hideLoading();
        return;
      } else {
        notify.success(this.$t('DOC_TYPE_FIELDS_CLONED'));
      }

      // refresh groups and fields
      const event = new CustomEvent('fetch_Groups_Fields_event', {});
      document.dispatchEvent(event);
    },
  },
});
</script>
