<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">Create New Field</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="'full-width '"
              v-model="new_model['title']"
              placeholder="Field Title"
              :error-message="new_model['title_error_msg']"
              :error="new_model['title_error']"
            >
            </q-input>
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="'full-width '"
              v-model="new_model['field_name']"
              placeholder="Field Name"
              :error-message="new_model['name_error_msg']"
              :error="new_model['name_error']"
            >
            </q-input>
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              v-model="new_model['field_type']"
              tabindex="0"
              :options="data_types"
              error-message="Field is required"
              :error="new_model['type_error']"
              emit-value
              map-options
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              tabindex="0"
              v-model="new_model['group_name']"
              error-message="Field is required"
              :error="new_model['group_error']"
              :options="group_list"
              emit-value
              map-options
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-checkbox
              :label="$t('required')"
              v-model="new_model['is_required']"
              size="30px"
            />

            <q-checkbox
              :label="$t('readonly')"
              v-model="new_model['is_readonly']"
              size="30px"
            />

            <q-checkbox
              :label="$t('hidden')"
              v-model="new_model['is_hidden']"
              size="30px"
            />

            <q-checkbox
              :label="$t('force_validation')"
              v-model="new_model['force_validation']"
              size="30px"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import {
  validateString,
  get_field_data_types,
  stringWithoutSpaces,
} from 'src/utils/general';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
    group_list: [] as any,
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_model: ref(model),
      token: ref(''),
      data_types: ref([] as any),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
    this.setFieldTypes();
  },
  methods: {
    setFieldTypes() {
      this.data_types = [{ label: 'Select Type', value: '' }].concat(
        get_field_data_types(),
      );
    },
    setNewModel() {
      this.new_model['field_name'] = '';
      this.new_model['group_name'] = '';
      this.new_model['field_type'] = '';
      this.new_model['title'] = '';
      this.new_model['is_required'] = false;
      this.new_model['is_readonly'] = false;
      this.new_model['is_hidden'] = false;
      this.new_model['force_validation'] = false;

      this.new_model['type_error'] = false;
      this.new_model['group_error'] = false;
      this.new_model['type_error'] = false;
      this.new_model['group_error'] = false;
      this.new_model['title_error'] = false;
      this.new_model['name_error'] = false;
      this.new_model['name_error_msg'] = '';
      this.new_model['title_error_msg'] = '';
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let response: any;
      let formData = new FormData();
      formData.append('title', this.new_model['title']);
      formData.append('field_name', this.new_model['field_name']);
      formData.append('group_name', this.new_model['group_name']);
      formData.append('doc_type_name', this.doc_type);
      formData.append('field_type', this.new_model['field_type']);

      formData.append('is_required', this.new_model['is_required']);
      formData.append('is_readonly', this.new_model['is_readonly']);
      formData.append('is_hidden', this.new_model['is_hidden']);
      formData.append('force_validation', this.new_model['force_validation']);
      formData.append('org_id', getOrgId());
      let token: string = await getAuthorizationToken();
      response = await axios.post(api.create_document_field, formData, {
        headers: {
          Authorization: token,
        },
      });

      if (
        response.data &&
        response.data.hasOwnProperty('success') &&
        response.data.success === false
      ) {
        throw { message: response.data.message };
      }

      notify.success('Field Created successfully');
      response.data['group_name'] = this.new_model['group_name'];
      const event = new CustomEvent('field_added', {
        detail: { data: response.data },
      });
      document.dispatchEvent(event);
    },

    validateRow(row: any) {
      let error = false;

      this.new_model['type_error'] = false;
      this.new_model['group_error'] = false;

      this.new_model['title_error'] = false;
      this.new_model['name_error'] = false;

      this.new_model['name_error_msg'] = '';
      this.new_model['title_error_msg'] = '';

      if (!row['title'] || row['title'].length == 0) {
        error = true;
        this.new_model['title_error_msg'] = 'Field Title is required';
        this.new_model['title_error'] = true;
      } else if (!validateString(row['title'])) {
        this.new_model['title_error_msg'] = i18n.t('field_only_characters');
        error = true;
        this.new_model['title_error'] = true;
      }

      if (!row['field_name'] || row['field_name'].length == 0) {
        this.new_model['name_error_msg'] = 'Field Name is required';
        error = true;
        this.new_model['name_error'] = true;
      } else if (!stringWithoutSpaces(row['field_name'])) {
        this.new_model['name_error_msg'] =
          'Field Name can only contain characters, numbers, hyphen and underscore';
        error = true;
        this.new_model['name_error'] = true;
      }

      if (!row['field_type'] || row['field_type'].length == 0) {
        this.new_model['type_error'] = true;
      }

      if (!row['group_name'] || row['group_name'].length == 0) {
        this.new_model['group_error'] = true;
      }

      return !error;
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
  },
});
</script>

<style lang="scss" scoped></style>
