<!--vbase-->
<template>
  <!-- Regex List -->
  <div class="flex flex-col gap-3">
    <!-- Toolbar -->
    <div class="flex items-center gap-2">
      <q-btn
        color="primary"
        class="mr-6"
        :label="$t('add_new')"
        @click="addNewDialog = true"
      />
      <q-space />
      <q-input outlined debounce="300" color="primary" v-model="filter">
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="doc_type_regexes_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      flat-style
      table-height="350px"
      @row-action="handleRowAction"
    >
      <template #body-cell-regexOrigin="{ row }">
        {{ getOriginLabel(row.regexOrigin) }}
      </template>
    </DocBitsTable>
  </div>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
  <!-- END Regex List -->

  <!-- Add New  -->
  <q-dialog
    v-model="addNewDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <CreateRegex
      :doc_type="doc_type"
      :language_origin_list="language_origin_list"
      :rows="rows"
    />
  </q-dialog>
  <!-- END Add New -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken, getRegexSaveUrl } from 'pages/APIs';
import axios from 'axios';
import type { dynamicObj } from 'src/pages/assets';

import CreateRegex from 'src/pages/Settings/CreateDocType/CreateRegex.vue';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
    list_data: [] as any,
    language_origin_list: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    CreateRegex,
    DocBitsTable,
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const lowerSearch = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        for (const [_key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(lowerSearch)) return true;
        }
        return false;
      });
    },
  },
  setup() {
    let data: any = [];
    const columns = ref(data);

    const rowActions: RowActionItem[] = [
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: any) => row.id !== '' && row.org_id !== DEFAULT_ORG_UUID,
      },
    ];

    return {
      loading: ref(false),
      columns,
      rows: ref(data),
      filter: ref(''),
      addNewDialog: ref(false),
      rowActions,
    };
  },
  watch: {
    list_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.prepareRows(newVal);
        }, 0);
      },
    },
  },
  mounted: function () {
    this.prepareColumns();
    this.prepareRows(this.list_data);
    document.addEventListener('regex_added', this.recordAdded);
  },
  unmounted: function () {
    // event listeners
    document.removeEventListener('regex_added', this.recordAdded);
  },
  methods: {
    prepareListView(data: any) {
      this.prepareRows(data);
    },
    prepareColumns() {
      this.columns = [
        {
          name: 'regexOrigin',
          label: this.$t('origin'),
          field: 'regexOrigin',
          align: 'left',
        },
        {
          name: 'regexValuePattern',
          label: this.$t('pattern'),
          field: 'regexValuePattern',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },
    prepareRows(data: any) {
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },
    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },
    getOriginLabel(originValue: string): string {
      const option = (this.language_origin_list as any[]).find(
        (opt: any) => opt.value === originValue,
      );
      return option ? option.label : originValue || '-';
    },
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === row.id);
        if (index !== -1) {
          this.handleDelete(row, index);
        }
      }
    },
    async handleDelete(row: any, index: number) {
      try {
        this.loading = true;
        let response: any;
        this.rows[index].is_deleted = true;

        let token: string = await getAuthorizationToken();
        let formData = new FormData();
        formData.append('data', JSON.stringify(this.rows));
        formData.append('org_id', getOrgId());

        response = await axios.post(
          api.post_data_fellowkv + getRegexSaveUrl(this.type),
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw { message: response.data.message };
        }

        const event = new CustomEvent('regex_deleted', {
          detail: { index: index },
        });
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    recordAdded(e: any) {
      this.addNewDialog = false;
    },
  },
});
</script>
