<!--vbase-->
<template>
  <div class="container create-doc-type">
    <div>
      <div class="row">
        <span class="text-h6 q-mb-md q-mx-auto">
          {{ step_labels[step] }}
        </span>
      </div>

      <!-- Wizard -->
      <q-stepper
        class="white-back"
        v-model="step"
        ref="stepper"
        flat
        alternative-labels
        color="primary"
        animated
      >
        <q-step
          name="doc"
          :title="$t('create')"
          icon="edit"
          done-icon="edit"
          active-icon="edit"
          done-color="green"
          :done="done_steps['doc']"
        >
          <q-form class="create-doc-form">
            <!-- field -->
            <div class="row">
              <!-- <div style="width: 20%; margin-top: 4px">
                {{ }}
              </div> -->
              <div class="full-width">
                <q-input
                  v-model="step1_model['name']"
                  :placeholder="$t('name')"
                  :readonly="isDocStep1Saved()"
                  outlined
                  dense
                >
                  <template v-slot:append>
                    <q-icon
                      name="error"
                      color="red"
                      tabindex="0"
                      class="cursor-pointer"
                      v-if="error_model['doc_name'] !== ''"
                    >
                      <q-tooltip>
                        {{ error_model['doc_name'] }}
                      </q-tooltip>
                    </q-icon>
                  </template>
                </q-input>
              </div>
            </div>

            <!-- field -->
            <div class="row items-center q-py-md">
              <q-checkbox
                v-model="step1_model['has_table']"
                :disable="isDocStep1Saved()"
              ></q-checkbox>
              <div class="q-pl-sm">
                {{ $t('has_table') }}
              </div>
            </div>

            <!--  field -->
            <div class="row">
              <div class="full-width">
                <q-input
                  v-model="step1_model['description']"
                  :readonly="isDocStep1Saved()"
                  :placeholder="$t('description')"
                  outlined
                  dense
                ></q-input>
              </div>
            </div>

            <!--  Doc type field -->
            <div class="row justify-center q-gutter-md q-mt-lg">
              <q-btn
                @click="step1_model['doc_type'] = 'auto'"
                :class="'doc-type-btn ' + (step1_model['doc_type'] == 'auto' ? 'selected' : '')"
                unelevated
                no-caps
                :label="$t('auto')"
              />
              <q-btn
                :class="'doc-type-btn ' + (step1_model['doc_type'] == 'regex' ? 'selected' : '')"
                @click="step1_model['doc_type'] = 'regex'"
                unelevated
                no-caps
                :label="$t('regex')"
              />
            </div>
          </q-form>
        </q-step>

        <q-step
          name="regex"
          :title="$t('create_regex')"
          v-if="step1_model['doc_type'] == 'regex'"
          icon="code"
          done-color="green"
          :done="done_steps['regex']"
        >
          <Regexes
            :doc_type="getDocTypeName()"
            :list_data="regexes"
            :language_origin_list="language_origin_list"
            :table_height="430"
          />
        </q-step>

        <q-step
          name="upload"
          :title="$t('upload')"
          v-if="step1_model['doc_type'] == 'auto'"
          icon="upload"
          done-icon="upload"
          active-icon="upload"
          done-color="green"
          :done="done_steps['upload']"
        >
          <TrainingList
            :doc_type="getDocTypeName()"
            :doc_type_key="getDocTypeKey()"
            :language_origin_list="language_origin_list"
            :max_value="training_doc_limit"
            :list_data="sample_files"
          />
        </q-step>

        <q-step
          name="fields_groups"
          :title="$t('fields_groups')"
          icon="text_fields"
          done-icon="text_fields"
          active-icon="text_fields"
          done-color="green"
          :done="done_steps['fields_groups']"
        >
          <q-tabs
            v-model="tab"
            dense
            class="text-grey"
            active-color="primary"
            indicator-color="primary"
            align="justify"
            active-class="highlighted-back"
          >
            <q-tab name="groups" :label="$t('groups')"></q-tab>
            <q-tab name="fields" :label="$t('fields')"></q-tab>
          </q-tabs>

          <q-separator></q-separator>

          <q-tab-panels v-model="tab" animated>
            <q-tab-panel name="groups" class="white-back">
              <Groups :doc_type="getDocTypeName()" :list_data="groups" />
            </q-tab-panel>

            <q-tab-panel name="fields" class="white-back">
              <Fields
                :doc_type="getDocTypeName()"
                :list_data="fields"
                :groups="groups"
              />
            </q-tab-panel>
          </q-tab-panels>
        </q-step>

        <q-step
          name="table_columns"
          :title="$t('table_columns')"
          v-if="step1_model['has_table'] === true"
          icon="table_chart"
          done-icon="table_chart"
          active-icon="table_chart"
          done-color="green"
          :done="done_steps['table_columns']"
        >
          <!--  -->
          <q-tabs
            v-model="table_column_tab"
            dense
            class="text-grey"
            active-color="primary"
            indicator-color="primary"
            align="justify"
            active-class="highlighted-back"
          >
            <q-tab name="tables" :label="$t('tables')"></q-tab>
            <q-tab name="columns" :label="$t('columns')"></q-tab>
          </q-tabs>

          <q-separator></q-separator>

          <q-tab-panels v-model="table_column_tab" animated>
            <q-tab-panel name="tables" class="white-back">
              <Tables :doc_type="getDocTypeKey()" :list_data="tables" />
            </q-tab-panel>

            <q-tab-panel name="columns" class="white-back">
              <TableColumns
                :table_height="430"
                :tables="tables"
                :list_data="table_columns"
              />
            </q-tab-panel>
          </q-tab-panels>
        </q-step>
      </q-stepper>

      <!-- navigation buttons -->
      <div class="row q-mt-md">
        <div class="q-mr-auto text-uppercase">
          <q-btn
            v-if="step != 'doc'"
            icon="arrow_back"
            @click="($refs.stepper as any)?.previous?.()"
            :label="$t('back')"
            class="q-ml-sm highlighted-back"
          ></q-btn>
        </div>

        <q-btn
          icon-right="arrow_forward"
          class="q-ml-sm q-ml-auto"
          @click="validateAndNext"
          color="primary"
          :label="$t(wizardNextButtonLabel())"
        ></q-btn>
      </div>
    </div>
  </div>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import Groups from 'src/pages/Settings/CreateDocType/Groups.vue';
import Fields from 'src/pages/Settings/CreateDocType/Fields.vue';
import Tables from 'src/pages/Settings/CreateDocType/Tables.vue';
import Regexes from 'src/pages/Settings/CreateDocType/Regexes.vue';
import { $, type createDocument, type dynamicObj } from 'src/pages/assets';
import TrainingList from 'src/pages/Settings/Components/ModelTraining/TrainingList.vue';
import TableColumns from 'src/pages/Settings/CreateDocType/TableColumns.vue';
import {
  removeSpacesWithUnderscore,
  validateString,
  isEmptyString,
} from 'src/utils/general';
import { useDropdownStore } from 'src/store/main';
import Loader from 'src/components/Loader.vue';
import {
  addOrgIdQueryString,
  getOrgId,
} from 'src/utils/organization/org_id_helper';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    TrainingList,
    Groups,
    Fields,
    TableColumns,
    Regexes,
    Tables,
    Loader,
  },
  data() {
    return {};
  },
  setup() {
    let createDocumentModel = {
      doc_type: 'auto',
      has_table: false,
      id: '',
      name: '',
      doc_type_name: '',
    } as createDocument;

    const dropdown_store = useDropdownStore();
    const { resetDocTypesSubDocTypes } = dropdown_store;

    return {
      resetDocTypesSubDocTypes,
      step1_model: ref(createDocumentModel),
      step: ref('doc'),
      done_steps: ref({} as dynamicObj),
      step_labels: ref({} as dynamicObj),
      error_model: ref({
        doc_name: '',
      } as dynamicObj),
      language_origin_list: ref([] as any),
      training_doc_count: ref(0),
      training_doc_limit: 10,
      fields_count: ref(0),
      tab: ref('groups'),
      sample_files: ref([] as any),
      groups: ref([] as any),
      fields: ref([] as any),
      doc_type: ref(''),
      regexes: ref([] as any),
      regex_limit: 2,
      tables: ref([] as any),
      table_columns: ref([] as any),
      table_column_tab: ref('tables'),
      loading: ref(false),
    };
  },
  watch: {
    doc_type: {
      handler: function (newVal, oldVal) {
        this.fetchSamplesFiles();
        this.fetchGroups();
        this.fetchFields();
        this.getDocumentTypeRegexes();

        this.fetchTables();
        this.fetchTableColumns();
      },
    },
  },
  mounted() {
    this.prepareSteps();
    this.handleLanguageOptions();

    document.addEventListener('group_added', this.groupAdded);
    document.addEventListener('group_deleted', this.groupDeleted);

    document.addEventListener('field_added', this.fieldAdded);
    document.addEventListener('field_deleted', this.fieldDeleted);

    document.addEventListener('refresh_sample_data', this.refreshSampleData);
    document.addEventListener('sample_file_delete', this.sampleFileDeleted);

    document.addEventListener('table_added', this.tableAdded);
    document.addEventListener('table_deleted', this.tableDeleted);

    document.addEventListener('regex_added', this.regexAdded);
    document.addEventListener('regex_deleted', this.regexDeleted);

    document.addEventListener('column_added', this.tableColumnAdded);
    document.addEventListener('column_deleted', this.tableColumnDeleted);

    document.addEventListener(
      'fetch_Groups_Fields_event',
      this.getGroupsAndFields,
    );

    // this.step1_model['doc_type_name'] = 'TEST3';
    // this.step1_model['name'] = 'TEST3';
    // this.step1_model['document_key'] = 'TEST3_23f3d697-7411-4c95-981d-faf089d266be';
    // this.step1_model['id'] = 'fff2a407-dd30-4784-bd59-0622980fef24';

    //  this.doc_type = this.step1_model['doc_type_name'];
  },
  unmounted: function () {
    document.removeEventListener('refresh_sample_data', this.refreshSampleData);
    document.removeEventListener('sample_file_delete', this.sampleFileDeleted);

    document.removeEventListener('group_added', this.groupAdded);
    document.removeEventListener('group_deleted', this.groupDeleted);

    document.removeEventListener('field_added', this.fieldAdded);
    document.removeEventListener('field_deleted', this.fieldDeleted);

    document.removeEventListener('table_added', this.tableAdded);
    document.removeEventListener('table_deleted', this.tableDeleted);

    document.removeEventListener('regex_added', this.regexAdded);
    document.removeEventListener('regex_deleted', this.regexAdded);

    document.removeEventListener('column_added', this.tableColumnAdded);
    document.removeEventListener('column_deleted', this.tableColumnDeleted);

    document.removeEventListener(
      'fetch_Groups_Fields_event',
      this.getGroupsAndFields,
    );
  },
  methods: {
    async handleLanguageOptions() {
      await this.fetchLanguageOptions();
    },
    async fetchLanguageOptions() {
      let response: any;
      try {
        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(api.get_items_from_dictionary + 'DOC_ORIGIN'),
          {
            headers: {
              Authorization: token,
            },
          },
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }

      if (!response.data || Object.keys(response.data).length === 0) {
        return;
      }
      this.language_origin_list = [];
      this.language_origin_list.push(
        Object.assign(
          {},
          {
            value: '',
            label: this.$t('amount_date_format_select'),
          },
        ),
      );
      for (const prop in response.data) {
        let option = response.data[prop] as dynamicObj;
        let description = !option.description ? '' : option.description;
        this.language_origin_list.push(
          Object.assign(
            {},
            {
              value: option.value,
              label: option.label,
              locale: option.locale,
              description: description.replaceAll('\\n', '<br />'),
            },
          ),
        );
      }
    },
    async validateAndNext() {
      try {
        this.loading = true;
        if (this.step == 'doc' && !this.isDocStep1Saved()) {
          this.validateDocCreateForm();
          await this.saveDocumnetType();
          await this.resetDocTypesSubDocTypes();
        }

        if (
          this.step == 'upload' &&
          this.sample_files.length < this.training_doc_limit
        ) {
          throw {
            message:
              this.$t('ERROR_UPLOAD') +
              this.training_doc_limit +
              this.$t('ERROR_UPLOAD_2'),
          };
        }

        if (this.step == 'regex' && this.regexes.length < this.regex_limit) {
          throw {
            message: this.$t('ERROR_PATTERN_REQUIRED'),
          };
        }

        // check only which are saved
        if (this.step == 'fields_groups' && this.fields.length < 1) {
          throw {
            message: this.$t('ERROR_CREATE_FIELDS'),
          };
        }

        let stepper = this.$refs['stepper'] as dynamicObj;

        const nextLabel = this.wizardNextButtonLabel();
        const isLastStep = nextLabel === 'finsih' ? true : false;

        if (isLastStep) {
          this.$router.push('/settings/document-types');
        }
        if (stepper) {
          this.done_steps[this.step] = true;
          stepper.next();
        }
      } catch (err: any) {
        logError(err);
        if (
          err != null &&
          typeof err == 'object' &&
          err.hasOwnProperty('message')
        ) {
          notify.error(err.message);
          return;
        }
      } finally {
        this.loading = false;
      }
    },

    isDocStep1Saved() {
      return this.step1_model['id'] === '' ? false : true;
    },

    validateDocCreateForm() {
      let validate = true;
      this.error_model['doc_name'] = '';

      if (!this.step1_model['name'] || this.step1_model['name'].length == 0) {
        this.error_model['doc_name'] = 'Field is Required';
        validate = false;
      }

      if (!validateString(this.step1_model['name'])) {
        this.error_model['doc_name'] = this.$t('only_characters_numbers');
        validate = false;
      }

      if (!validate) {
        throw 'Step 1 failed';
      }
    },
    prepareSteps() {
      // wait for language change
      setTimeout(() => {
        this.step_labels = {
          doc: this.$t('create_doc'),
          upload: this.$t('upload_training_doc'),
          regex: this.$t('create_regex'),
          fields_groups: this.$t('create_fields_groups'),
          table_columns: this.$t('table_columns'),
        };
      }, 10);

      this.done_steps = {
        doc: false,
        upload: false,
        regex: false,
        fields_groups: false,
        table_columns: false,
      };
    },

    async saveDocumnetType() {
      this.step1_model['doc_type_name'] = removeSpacesWithUnderscore(
        this.step1_model['name'],
      );

      let formData = new FormData();
      formData.append('doc_type_name', this.step1_model['doc_type_name']);
      formData.append('has_table', this.step1_model['has_table'].toString());
      formData.append('title', this.step1_model['name']);
      formData.append('org_id', getOrgId());

      let response: any;
      let token: string = await getAuthorizationToken();
      response = await axios.post(api.create_document_type, formData, {
        headers: {
          Authorization: 'Bearer ' + token,
        },
      });

      if (
        response.data &&
        response.data.hasOwnProperty('success') &&
        response.data.success === false
      ) {
        throw { message: response.data.message };
      }

      this.step1_model['document_key'] = response.data.document_key;
      this.step1_model['doc_type_name'] = response.data.document_name;
      this.step1_model['id'] = response.data.id;
      this.doc_type = this.step1_model['doc_type_name'];
    },
    getDocTypeName() {
      return this.step1_model['doc_type_name'];
    },
    getDocTypeKey() {
      return this.step1_model['document_key'];
    },

    setFieldsCount(e: any) {
      if (!e) {
        return;
      }
      this.fields_count = e.detail;
    },
    wizardNextButtonLabel() {
      let label = 'next';
      if (
        this.step === 'fields_groups' &&
        this.step1_model['has_table'] === false
      ) {
        label = 'finsih';
      }

      if (
        this.step === 'table_columns' &&
        this.step1_model['has_table'] === true
      ) {
        label = 'finsih';
      }

      return label;
    },
    refreshSampleData() {
      this.fetchSamplesFiles();
    },
    sampleFileDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let id = e.detail;
      for (let [index, col] of Object.entries(this.sample_files)) {
        const column = col as dynamicObj;
        if (column.id === id) {
          this.sample_files.splice(index, 1);
        }
      }
    },
    async fetchSamplesFiles() {
      let response: any;
      try {
        if (isEmptyString(this.getDocTypeName())) {
          return;
        }

        let formData = new FormData();
        formData.append('doc_type', this.getDocTypeKey());
        formData.append('org_id', getOrgId());

        let token: string = await getAuthorizationToken();
        response = await axios.post(
          api.get_sample_documents_trainer,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        let data = [];
        for (let [index, col] of Object.entries(response.data)) {
          const column = col as dynamicObj;
          let newRow: dynamicObj = { ...column };
          data.push(newRow);
        }
        this.sample_files = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    groupAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.groups.push(e.detail.data);
    },

    groupDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let index = e.detail.index;
      this.groups.splice(index, 1);
      this.fetchFields();
    },

    async fetchGroups() {
      let response: any;
      try {
        if (isEmptyString(this.doc_type)) {
          return;
        }

        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(
            api.get_document_field_groups +
              '?doc_type_name=' +
              this.getDocTypeName(),
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        let groupMap = new Map();

        let data: any = [];
        for (let [index, col] of Object.entries(response.data.data)) {
          const column = col as dynamicObj;
          let newRow: dynamicObj = { ...column };
          data.push(newRow);

          groupMap.set(newRow.id, newRow);
        }

        // comment out bellow section once group api is fixed and groups are grouped by group id
        // start
        data = [];
        groupMap.forEach((value: any, key: string) => {
          data.push(value);
        });
        // end

        this.groups = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    getGroupsAndFields(e: any) {
      this.fetchGroups();
      this.fetchFields();
    },
    fieldAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.fields.push(e.detail.data);
    },

    fieldDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let index = e.detail.index;
      this.fields.splice(index, 1);
    },

    async fetchFields() {
      let response: any;
      try {
        if (isEmptyString(this.doc_type)) {
          return;
        }

        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(api.get_field_settings_by_type),
          {
            params: {
              doc_type: this.getDocTypeKey(),
              profile: '',
            },
            headers: {
              Authorization: token,
            },
          },
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        let api_data = response.data.field_setting;
        let data = [] as any;
        Array.from(api_data).forEach((group: any) => {
          Array.from(group.rows).forEach((rows: any) => {
            Array.from(rows).forEach((row: any) => {
              row['group_name'] = group.name;
              row['field_type'] = row.field_type.toUpperCase();
              let newRow: dynamicObj = { ...row };
              data.push(newRow);
            });
          });
        });
        this.fields = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    regexAdded(e: any) {
      this.getDocumentTypeRegexes();
    },

    regexDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let index = e.detail.index;
      this.regexes.splice(index, 1);
    },

    async getDocumentTypeRegexes() {
      if (isEmptyString(this.getDocTypeName())) {
        throw { message: 'Document Type is missing' };
      }

      this.loading = true;
      this.regexes = [] as any;
      let response: any;
      let token: string = await getAuthorizationToken();

      let formData = new FormData();
      let data = {
        regexType: this.getDocTypeName(),
      };
      formData.append('data', JSON.stringify(data));
      formData.append('org_id', getOrgId());

      response = await axios.post(
        api.post_data_fellowkv + api.get_document_type_regexes,
        formData,
        {
          headers: {
            Authorization: token,
          },
        },
      );

      if (!response.data) {
        throw { message: 'No Data return from api' };
      }
      if (response.data.hasOwnProperty('message')) {
        throw response.data;
      }

      response.data.forEach((row: any, index: any) => {
        this.regexes.push(row);
      });
      this.loading = false;
    },

    tableAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.tables.push(e.detail.data);
    },

    tableDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let index = e.detail.index;
      this.tables.splice(index, 1);
    },

    async fetchTables() {
      let response: any;
      try {
        if (isEmptyString(this.doc_type)) {
          return;
        }

        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(
            api.get_document_tables + '?doc_type=' + this.getDocTypeKey(),
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        let data = [];
        for (let [index, col] of Object.entries(response.data.data)) {
          const column = col as dynamicObj;
          let newRow: dynamicObj = { ...column };
          data.push(newRow);
        }
        this.tables = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    tableColumnAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.table_columns.push(e.detail.data);
    },

    tableColumnDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let index = e.detail.index;
      this.table_columns.splice(index, 1);
    },

    async fetchTableColumns() {
      let response: any;
      try {
        if (isEmptyString(this.doc_type)) {
          return;
        }

        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(
            api.get_document_tables_with_columns +
              '?doc_type=' +
              this.getDocTypeKey(),
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        let data = [];
        for (let [tbl_name, tbl] of Object.entries(response.data.data)) {
          const table = tbl as dynamicObj;
          for (let [index, col] of Object.entries(table)) {
            const row = col as dynamicObj;
            let newRow: dynamicObj = { ...row };
            newRow['table_name'] = tbl_name;
            data.push(newRow);
          }
        }

        this.table_columns = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>
