<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title><span class="text-weight-bold text-white">Create New Regex</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="'full-width '"
              v-model="new_model['regexValuePattern']"
              placeholder="Pattern"
              :error-message="new_model['pattern_error_msg']"
              :error="new_model['pattern_error']"
            >
            </q-input>
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              tabindex="0"
              v-model="new_model['regexOrigin']"
              error-message="Field is required"
              :error="new_model['origin_error']"
              :options="language_origin_list"
              emit-value
              map-options
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
        <q-btn
          v-if="!new_model['regex_validated']"
          color="orange"
          class="mr-6"
          :label="$t('validate')"
          @click="validatePattern()"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken, getRegexSaveUrl } from 'pages/APIs';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
    language_origin_list: {
      type: Array,
      default: () => [],
    },
    type: {
      type: String,
      default: 'document',
    },
    rows: [] as any,
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_model: ref(model),
      token: ref(''),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['regexType'] = this.doc_type;
      this.new_model['regexValuePattern'] = '';
      this.new_model['regexOrigin'] = '';
      this.new_model['org_id'] = getUserDetailFromkey('org_id');

      this.new_model['regex_validated'] = false;
      this.new_model['origin_error'] = false;
      this.new_model['pattern_error'] = false;
      this.new_model['pattern_error_msg'] = '';
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let response: any;
      let token: string = await getAuthorizationToken();
      let data = JSON.parse(JSON.stringify(this.rows));
      data.push(this.new_model);
      let formData = new FormData();
      formData.append('data', JSON.stringify(data));
      formData.append('org_id', getOrgId());

      response = await axios.post(
        api.post_data_fellowkv + getRegexSaveUrl(this.type),
        formData,
        {
          headers: {
            Authorization: token,
          },
        },
      );

      if (response.data.success === false) {
        throw { message: response.data.message };
      }

      const event = new CustomEvent('regex_added', { detail: {} });
      document.dispatchEvent(event);
    },

    validateRow(row: any) {
      let error = false;
      this.resetErrors();

      if (this.isPatternEmpty(row)) {
        error = true;
      } else if (!this.new_model['regex_validated']) {
        error = true;
        this.new_model['pattern_error_msg'] = 'Please validate Pattern';
        this.new_model['pattern_error'] = true;
      }

      if (!row['regexOrigin'] || row['regexOrigin'].length == 0) {
        this.new_model['origin_error'] = true;
        error = true;
      }

      return !error;
    },

    isPatternEmpty(row: any) {
      let error = false;
      if (!row['regexValuePattern'] || row['regexValuePattern'].length == 0) {
        error = true;
        this.new_model['pattern_error_msg'] = 'Pattern is required';
        this.new_model['pattern_error'] = true;
      }
      return error;
    },

    resetErrors() {
      this.new_model['pattern_error'] = false;
      this.new_model['pattern_error_msg'] = '';
      this.new_model['origin_error'] = false;
    },

    async validatePattern() {
      try {
        this.resetErrors();
        if (this.isPatternEmpty(this.new_model)) {
          return;
        }
        this.loading = true;
        let response: any;
        let token: string = await getAuthorizationToken();

        let formData = new FormData();
        formData.append(
          'patterns',
          JSON.stringify(this.getValidatePatternData()),
        );
        formData.append('org_id', getOrgId());

        response = await axios.post(api.validate_patterns, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw { message: response.data.message };
        }

        this.updateRows(response.data.data);
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
        this.loading = false;
      }
    },

    updateRows(result: any) {
      for (let [pattern, validate] of Object.entries(result)) {
        const new_validate = validate === false ? false : true;
        this.new_model['regex_validated'] = new_validate;
        if (new_validate === false) {
          this.new_model['pattern_error_msg'] = 'Valid pattern is required';
          this.new_model['pattern_error'] = true;
        }
      }
    },

    getValidatePatternData() {
      let regexes = [] as string[];
      const regex =
        !this.new_model['regexValuePattern'] ||
        this.new_model['regexValuePattern'] === ''
          ? ''
          : this.new_model['regexValuePattern'].toString();
      regexes.push(regex);

      return regexes;
    },

    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
  },
});
</script>

<style lang="scss" scoped></style>
