<!--vbase-->
<template>
  <!-- Table Columns List -->
  <div class="flex flex-col gap-3">
    <!-- Toolbar -->
    <div class="flex items-center gap-2">
      <q-input dense outlined debounce="300" color="primary" v-model="filter">
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-space />
      <q-btn
        color="primary"
        class="mr-6"
        :label="$t('add_new')"
        @click="addNewDialog = true"
      />
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="doc_type_table_columns_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      flat-style
      table-height="350px"
      @row-action="handleRowAction"
    >
      <template #body-cell-column_name="{ row }">
        <q-input
          borderless
          tabindex="0"
          v-model="row.column_name"
          :readonly="row.id !== ''"
        />
      </template>
      <template #body-cell-table_name="{ row }">
        <q-select
          borderless
          tabindex="0"
          v-model="row.table_name"
          :readonly="row.id !== ''"
          :options="tables_list"
          emit-value
          map-options
        />
      </template>
    </DocBitsTable>
  </div>
  <!-- END Table Columns List -->

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

  <!-- Add New  -->
  <q-dialog
    v-model="addNewDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <CreateColumn
      :doc_type="doc_type"
      :columns_list="columns_list"
      :tables_list="tables_list"
    />
  </q-dialog>
  <!-- END Add New -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { api, getAuthorizationToken } from 'pages/APIs';
import axios from 'axios';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import CreateColumn from 'src/pages/Settings/CreateDocType/CreateColumn.vue';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [displayFieldLabel],
  props: {
    doc_type: {
      type: String,
      default: '',
    },
    list_data: {} as any,
    tables: [] as any,
  },
  components: {
    CreateColumn,
    DocBitsTable,
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const lowerSearch = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        for (const [_key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(lowerSearch)) return true;
        }
        return false;
      });
    },
  },
  setup() {
    let data: any = [];
    const columns = ref(data);
    let model: { [k: string]: any } = {};

    const rowActions: RowActionItem[] = [
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: any) => row.id !== '' && row.org_id !== DEFAULT_ORG_UUID,
      },
    ];

    return {
      loading: ref(false),
      columns,
      rows: ref(data),
      filter: ref(''),
      addNewDialog: ref(false),
      columns_list: ref(model),
      tables_list: ref([] as any),
      rowActions,
    };
  },
  watch: {
    list_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.prepareRows(newVal);
        }, 0);
      },
    },
  },
  mounted: function () {
    this.prepareColumns();
    this.prepareRows(this.list_data);
    this.prepareTableList();
    document.addEventListener('column_added', this.recordAdded);
  },
  unmounted: function () {
    document.removeEventListener('column_added', this.recordAdded);
  },
  methods: {
    prepareTableList() {
      this.tables_list = [] as any;
      this.tables_list.push(
        Object.assign(
          {},
          {
            value: '',
            label: this.$t('select_table'),
          },
        ),
      );
      for (let [index, item] of Object.entries(this.tables)) {
        const row = item as dynamicObj;
        this.tables_list.push(
          Object.assign(
            {},
            {
              value: row.table_name,
              label: row.table_name,
            },
          ),
        );
      }
    },

    prepareListView(data: any) {
      this.prepareRows(data);
    },
    prepareColumns() {
      this.columns = [
        {
          name: 'column_name',
          label: this.$t('column_name'),
          field: 'column_name',
          align: 'left',
        },
        {
          name: 'table_name',
          label: this.$t('table_name'),
          field: 'table_name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },
    prepareRows(data: any) {
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
        if (row && row.hasOwnProperty('column_name')) {
          this.addToColumnList(row.column_name);
        }
      }
    },
    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },
    addToColumnList(column_name: string) {
      this.columns_list[column_name] = column_name;
    },
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === row.id);
        if (index !== -1) {
          this.handleDelete(row, index);
        }
      }
    },
    async handleDelete(row: any, index: number) {
      try {
        this.loading = true;
        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.delete(
          addOrgIdQueryString(api.delete_table_column + '/' + row.id),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (!response.data.success || response.data.success !== true) {
          throw response;
        }

        const event = new CustomEvent('column_deleted', {
          detail: { index: index },
        });
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    recordAdded(e: any) {
      this.addNewDialog = false;
    },
  },
});
</script>
