<!--vbase-->
<template>
  <!-- Fields List -->
  <div class="flex flex-col gap-3">
    <!-- Toolbar -->
    <div class="flex items-center gap-2">
      <q-btn
        color="primary"
        class="mr-6"
        :label="$t('add_new')"
        @click="addNewDialog = true"
      />
      <q-space />
      <q-input outlined debounce="300" color="primary" v-model="filter">
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="doc_type_fields_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      flat-style
      table-height="350px"
      @row-action="handleRowAction"
    >
      <template #body-cell-title="{ row }">
        <q-input
          borderless
          tabindex="0"
          v-model="row.title"
          :readonly="row.id !== ''"
        />
      </template>
      <template #body-cell-field_name="{ row }">
        <q-input
          borderless
          tabindex="0"
          v-model="row.field_name"
          :readonly="row.id !== ''"
        />
      </template>
      <template #body-cell-field_type="{ row }">
        <q-select
          borderless
          tabindex="0"
          v-model="row.field_type"
          :readonly="row.id !== ''"
          :options="data_types"
          emit-value
          map-options
        />
      </template>
      <template #body-cell-group_name="{ row }">
        <q-select
          borderless
          tabindex="0"
          v-model="row.group_name"
          :readonly="row.id !== ''"
          :options="group_list"
          emit-value
          map-options
        />
      </template>
    </DocBitsTable>
  </div>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
  <!-- END Fields List -->

  <!-- Add New  -->
  <q-dialog
    v-model="addNewDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <CreateField :doc_type="doc_type" :group_list="group_list" />
  </q-dialog>
  <!-- END Add New -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import { api, getAuthorizationToken } from 'pages/APIs';
import axios from 'axios';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import CreateField from 'src/pages/Settings/CreateDocType/CreateField.vue';
import { isObjectEmtpy, get_field_data_types } from 'src/utils/general';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [displayFieldLabel],
  props: {
    doc_type: {
      type: String,
      default: '',
    },
    list_data: {} as any,
    groups: {} as any,
  },
  components: {
    CreateField,
    DocBitsTable,
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const lowerSearch = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        for (const [key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(lowerSearch)) return true;
          // Also search group name display label
          if (key === 'group_name' && val && this.group_list_flat[String(value)]) {
            if (this.group_list_flat[String(value)].toLowerCase().includes(lowerSearch)) return true;
          }
        }
        return false;
      });
    },
  },
  setup() {
    let data: any = [];
    const columns = ref(data);
    let model = {} as { [k: string]: any };

    const rowActions: RowActionItem[] = [
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: any) => row.id !== '' && row.org_id !== DEFAULT_ORG_UUID,
      },
    ];

    return {
      loading: ref(false),
      columns,
      rows: ref(data),
      filter: ref(''),
      group_list: ref(data),
      group_list_flat: ref(model),
      addNewDialog: ref(false),
      data_types: get_field_data_types(),
      rowActions,
    };
  },
  watch: {
    list_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.prepareRows(newVal);
        }, 0);
      },
    },
    groups: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.fetchGroups(newVal);
        }, 0);
      },
    },
  },
  mounted: function () {
    this.prepareColumns();
    this.fetchGroups(this.groups);
    this.prepareRows(this.list_data);
    document.addEventListener('field_added', this.recordAdded);
  },
  unmounted: function () {
    document.removeEventListener('field_added', this.recordAdded);
  },
  methods: {
    recordAdded(e: any) {
      this.addNewDialog = false;
    },
    fetchGroups(groups: any) {
      this.group_list = [] as any;
      this.group_list.push(
        Object.assign(
          {},
          {
            value: '',
            label: 'Select Group',
          },
        ),
      );
      for (let [index, item] of Object.entries(groups)) {
        const row = item as dynamicObj;
        this.group_list.push(
          Object.assign(
            {},
            {
              value: row.group_name,
              label: this.displayFieldLabel(row),
            },
          ),
        );
      }
      this.flatLanguageList();
    },
    flatLanguageList() {
      if (!isObjectEmtpy(this.group_list_flat)) {
        return;
      }

      for (let [key, value] of Object.entries(this.group_list)) {
        let val = value as any;
        this.group_list_flat[val.value] = val.label;
      }
    },

    prepareColumns() {
      this.columns = [
        {
          name: 'title',
          label: this.$t('field_title'),
          field: 'title',
          align: 'left',
        },
        {
          name: 'field_name',
          label: this.$t('field_name'),
          field: 'field_name',
          align: 'left',
        },
        {
          name: 'field_type',
          label: this.$t('type'),
          field: 'field_type',
          align: 'left',
        },
        {
          name: 'group_name',
          label: this.$t('groups'),
          field: 'group_name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },
    prepareRows(data: any) {
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },
    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      newRow['title'] = this.displayFieldLabel(row);
      newRow['error'] = false;
      newRow['error_messages'] = '';
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === row.id);
        if (index !== -1) {
          this.handleDelete(row.id, index);
        }
      }
    },

    async handleDelete(id: any, index: number) {
      try {
        if (id === '') {
          return;
        }
        this.loading = true;
        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.delete(
          addOrgIdQueryString(api.delete_document_field + '/' + id),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        const event = new CustomEvent('field_deleted', {
          detail: { index: index },
        });
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
